from fastapi import APIRouter
from app.config import settings

router = APIRouter()


@router.get("/status")
def status():
    configured = bool(settings.instagram_access_token and settings.instagram_business_account_id)
    return {"service": "instagram", "configured": configured}

from fastapi import APIRouter
from app.config import settings

router = APIRouter()


@router.get("/status")
def status():
    configured = bool(settings.facebook_page_access_token and settings.facebook_page_id)
    return {"service": "facebook", "configured": configured}

from fastapi import APIRouter
from app.config import settings

router = APIRouter()


@router.get("/status")
def status():
    configured = bool(settings.whatsapp_access_token and settings.whatsapp_phone_number_id)
    return {"service": "whatsapp", "configured": configured}

from fastapi import APIRouter
from app.config import settings

router = APIRouter()


@router.get("/status")
def status():
    configured = bool(settings.x_bearer_token)
    return {"service": "x", "configured": configured}

from fastapi import APIRouter
from app.config import settings

router = APIRouter()


@router.get("/status")
def status():
    configured = bool(settings.ms_client_id and settings.ms_client_secret and settings.ms_tenant_id)
    return {"service": "excel", "configured": configured}

from fastapi import APIRouter
from pydantic import BaseModel

router = APIRouter()


class AssistantRequest(BaseModel):
    task: str  # e.g. "organize" | "clean" | "summarize"
    text: str


@router.post("/run")
def run_assistant(req: AssistantRequest):
    # المرحلة القادمة: الاتصال الفعلي بنموذج الذكاء الاصطناعي
    return {"task": req.task, "result": "قيد التطوير — سيتم ربط نموذج AI هنا"}

from fastapi import APIRouter
from pydantic import BaseModel
from typing import Optional

router = APIRouter()


class Automation(BaseModel):
    name: str
    trigger: str          # مثال: "whatsapp.message_received"
    condition: Optional[dict] = None  # مثال: {"field": "from", "op": "contains", "value": "+20"}
    action: dict          # مثال: {"type": "excel.append_row", "params": {...}}
    enabled: bool = True


AUTOMATIONS: list[Automation] = []


@router.get("/")
def list_automations():
    return AUTOMATIONS


@router.post("/")
def create_automation(a: Automation):
    AUTOMATIONS.append(a)
    return a

