async function loadServices() {
  const services = ["instagram", "facebook", "whatsapp", "x", "excel"];
  const ul = document.getElementById("services");
  for (const s of services) {
    try {
      const res = await fetch(`/api/${s}/status`);
      const data = await res.json();
      const li = document.createElement("li");
      li.textContent = `${data.service}: ${data.configured ? "✅ مُعدّة" : "⚠️ غير مُعدّة (أضف المفاتيح في .env)"}`;
      ul.appendChild(li);
    } catch (e) {
      console.error(e);
    }
  }
}
loadServices();

