import operator
import logging
from typing import Any, Callable

from pydantic import BaseModel, Field

logger = logging.getLogger("nexa.automations")


class Condition(BaseModel):
    field: str
    op: str  # equals | contains | gt | lt
    value: Any


class Action(BaseModel):
    type: str  # مثال: "log", "excel.append_row", "whatsapp.send_message"
    params: dict = Field(default_factory=dict)


class Automation(BaseModel):
    id: int | None = None
    name: str
    trigger: str
    condition: Condition | None = None
    action: Action
    enabled: bool = True


_OPS: dict[str, Callable[[Any, Any], bool]] = {
    "equals": operator.eq,
    "contains": lambda a, b: str(b) in str(a),
    "gt": operator.gt,
    "lt": operator.lt,
}


def check_condition(cond: Condition | None, event_data: dict) -> bool:
    if cond is None:
        return True
    fn = _OPS.get(cond.op)
    if fn is None:
        logger.warning(f"unknown condition op: {cond.op}")
        return False
    actual = event_data.get(cond.field)
    if actual is None:
        return False
    try:
        if cond.op in ("gt", "lt"):
            return fn(float(actual), float(cond.value))
        return fn(actual, cond.value)
    except (TypeError, ValueError):
        return False


# --- Action handlers (هتبقى stubs لحد ما نربط الخدمات الحقيقية) ---
def _action_log(params: dict, event: dict) -> dict:
    msg = params.get("message", f"Event: {event}")
    logger.info(f"[ACTION:log] {msg}")
    return {"ok": True, "message": msg}


def _action_stub(service: str):
    def handler(params: dict, event: dict) -> dict:
        logger.info(f"[ACTION:{service}] params={params} event_keys={list(event)}")
        return {"ok": True, "note": f"{service}: سيتم التنفيذ بعد ربط الخدمة"}
    return handler


ACTION_HANDLERS: dict[str, Callable[[dict, dict], dict]] = {
    "log": _action_log,
    "excel.append_row": _action_stub("excel.append_row"),
    "whatsapp.send_message": _action_stub("whatsapp.send_message"),
    "instagram.reply_comment": _action_stub("instagram.reply_comment"),
    "facebook.publish_post": _action_stub("facebook.publish_post"),
    "x.post_tweet": _action_stub("x.post_tweet"),
}


class AutomationEngine:
    def __init__(self):
        self._automations: list[Automation] = []
        self._next_id = 1
        self.logs: list[dict] = []

    def create(self, a: Automation) -> Automation:
        a.id = self._next_id
        self._next_id += 1
        self._automations.append(a)
        return a

    def list(self) -> list[Automation]:
        return list(self._automations)

    def delete(self, automation_id: int) -> bool:
        before = len(self._automations)
        self._automations = [a for a in self._automations if a.id != automation_id]
        return len(self._automations) < before

    def handle_event(self, trigger: str, event_data: dict) -> list[dict]:
        """نقطة الدخول عند وصول حدث (من webhook مثلًا)."""
        results = []
        for a in self._automations:
            if not a.enabled or a.trigger != trigger:
                continue
            if not check_condition(a.condition, event_data):
                continue
            handler = ACTION_HANDLERS.get(a.action.type)
            if handler is None:
                result = {"automation": a.name, "ok": False, "error": f"unknown action {a.action.type}"}
            else:
                result = {"automation": a.name, **handler(a.action.params, event_data)}
            self.logs.append({"trigger": trigger, "automation": a.name, "result": result})
            results.append(result)
        return results


engine = AutomationEngine()

