async function loadServices() {
  const services = ["instagram", "facebook", "whatsapp", "x", "excel"];
  const ul = document.getElementById("services");
  ul.innerHTML = "";
  for (const s of services) {
    const data = await api(`/api/${s}/status`);
    const li = document.createElement("li");
    li.textContent = `${data.service}: ${data.configured ? "✅ مُعدّة" : "⚠️ غير مُعدّة (أضف المفاتيح في .env)"}`;
    ul.appendChild(li);
  }
}

async function loadAutomations() {
  const list = await api("/api/automations/");
  const ul = document.getElementById("automations");
  ul.innerHTML = "";
  for (const a of list) {
    const li = document.createElement("li");
    const cond = a.condition ? `${a.condition.field} ${a.condition.op} ${a.condition.value}` : "بدون شرط";
    li.textContent = `${a.name} | ${a.trigger} | ${cond} | → ${a.action.type} `;
    const del = document.createElement("button");
    del.textContent = "حذف";
    del.onclick = async () => { await api(`/api/automations/${a.id}`, { method: "DELETE" }); loadAutomations(); };
    li.appendChild(del);
    ul.appendChild(li);
  }
}

async function loadActions() {
  const actions = await api("/api/automations/actions");
  const sel = document.getElementById("action-type");
  sel.innerHTML = "";
  for (const a of actions) {
    const opt = document.createElement("option");
    opt.value = a; opt.textContent = a;
    sel.appendChild(opt);
  }
}

async function loadLogs() {
