import sqlite3
import threading
from datetime import datetime, timezone
from pathlib import Path

from app.config import settings

_lock = threading.Lock()
_conn: sqlite3.Connection | None = None


def _now() -> str:
    return datetime.now(timezone.utc).isoformat()


def get_conn() -> sqlite3.Connection:
    global _conn
    with _lock:
        if _conn is None:
            Path(settings.db_path).parent.mkdir(parents=True, exist_ok=True)
            _conn = sqlite3.connect(settings.db_path, check_same_thread=False)
            _conn.row_factory = sqlite3.Row
            _init()
        return _conn


def _init():
    conn = _conn
    conn.executescript(
        """
        CREATE TABLE IF NOT EXISTS customers (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            phone TEXT UNIQUE NOT NULL,
            name TEXT,
            created_at TEXT
        );
        CREATE TABLE IF NOT EXISTS conversations (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            customer_id INTEGER NOT NULL REFERENCES customers(id),
            source TEXT NOT NULL DEFAULT 'whatsapp',
            started_at TEXT,
            last_message_at TEXT
        );
        CREATE TABLE IF NOT EXISTS messages (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            conversation_id INTEGER NOT NULL REFERENCES conversations(id),
            direction TEXT NOT NULL,  -- in | out
            body TEXT,
            intent TEXT,
            created_at TEXT
        );
        CREATE TABLE IF NOT EXISTS integration_errors (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            integration TEXT,
            message TEXT,
            created_at TEXT
        );
        CREATE TABLE IF NOT EXISTS meta (
            key TEXT PRIMARY KEY,
            value TEXT
        );
        """
    )
    conn.commit()


def execute(sql: str, params: tuple = ()) -> sqlite3.Cursor:
    with _lock:
        conn = get_conn()
        cur = conn.execute(sql, params)
        conn.commit()
        return cur


def query(sql: str, params: tuple = ()) -> list[dict]:
    with _lock:
        conn = get_conn()
        rows = conn.execute(sql, params).fetchall()
        return [dict(r) for r in rows]


def set_meta(key: str, value: str):
    execute("INSERT INTO meta(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value", (key, value))


def get_meta(key: str) -> str | None:
    rows = query("SELECT value FROM meta WHERE key=?", (key,))
    return rows[0]["value"] if rows else None


def log_error(integration: str, message: str):
    execute("INSERT INTO integration_errors(integration,message,created_at) VALUES(?,?,?)", (integration, message, _now()))


def recent_errors(limit: int = 20) -> list[dict]:
    return query("SELECT * FROM integration_errors ORDER BY id DESC LIMIT ?", (limit,))

"""Abstraction موحّد لكل تكاملات الخدمات الخارجية."""
from abc import ABC, abstractmethod


class BaseIntegration(ABC):
    name: str = "base"

    @abstractmethod
    def is_configured(self) -> bool:
        """هل المفاتيح المطلوبة موجودة في الـ environment؟"""

