import logging
import time
from typing import Any

import httpx

logger = logging.getLogger("nexa.http")


def post_with_retry(url: str, *, headers: dict, json: dict, attempts: int = 3, timeout: float = 20.0) -> httpx.Response:
    """POST مع retry بسيط وbackoff. يرمي آخر exception أو يرجع آخر response."""
    last_exc: Exception | None = None
    for i in range(1, attempts + 1):
        try:
            with httpx.Client(timeout=timeout) as client:
                resp = client.post(url, headers=headers, json=json)
                if resp.status_code < 500:
                    return resp
                logger.warning(f"attempt {i}/{attempts} got {resp.status_code}: {resp.text[:200]}")
        except (httpx.TimeoutException, httpx.TransportError) as e:
            last_exc = e
            logger.warning(f"attempt {i}/{attempts} failed: {e}")
        if i < attempts:
            time.sleep(2 ** (i - 1))
    if last_exc:
        raise last_exc
    return resp

