class WhatsAppIntegration(BaseIntegration):
    name = "whatsapp"

    def is_configured(self) -> bool:
        return bool(settings.whatsapp_access_token and settings.whatsapp_phone_number_id)

    def verify_webhook(self, params: dict) -> dict:
        mode = params.get("hub.mode")
        token = params.get("hub.verify_token")
        challenge = params.get("hub.challenge")
        if mode == "subscribe" and token and token == settings.whatsapp_verify_token:
            db.set_meta("whatsapp_webhook_verified_at", _utcnow())
            return {"ok": True, "challenge": challenge}
        return {"ok": False}

    def parse_event(self, payload: dict) -> list[dict]:
        events = []
        for entry in payload.get("entry", []):
            for change in entry.get("changes", []):
                value = change.get("value", {})
                contacts = {c.get("wa_id"): c.get("profile", {}).get("name") for c in value.get("contacts", [])}
                for msg in value.get("messages", []):
                    if msg.get("type") != "text":
                        continue
                    events.append(
                        {
                            "source": "whatsapp",
                            "trigger": "whatsapp.message_received",
                            "data": {
                                "from": msg.get("from"),
                                "name": contacts.get(msg.get("from")),
                                "text": msg.get("text", {}).get("body", ""),
                                "message_id": msg.get("id"),
                                "timestamp": msg.get("timestamp"),
                            },
                        }
                    )
        return events

    def send_message(self, to: str, text: str) -> dict:
        if not self.is_configured():
            db.log_error("whatsapp", "Cannot send: access token / phone number id missing")
            return {"ok": False, "error": "not_configured"}
        url = f"https://graph.facebook.com/{settings.whatsapp_api_version}/{settings.whatsapp_phone_number_id}/messages"
        headers = {
            "Authorization": f"Bearer {settings.whatsapp_access_token}",
            "Content-Type": "application/json",
        }
        payload = {
            "messaging_product": "whatsapp",
            "to": to,
            "type": "text",
            "text": {"body": text},
        }
        try:
            resp = post_with_retry(url, headers=headers, json=payload)
        except Exception as e:
            db.log_error("whatsapp", f"send failed: {e}")
            return {"ok": False, "error": str(e)}
        if resp.status_code >= 400:
            db.log_error("whatsapp", f"send {resp.status_code}: {resp.text[:300]}")
            return {"ok": False, "error": resp.text}
        return {"ok": True, "response": resp.json()}


