    params = dict(request.query_params)
    result = whatsapp.verify_webhook(params)
    if result["ok"]:
        return PlainTextResponse(result["challenge"])
    return PlainTextResponse("Forbidden", status_code=403)


@router.post("/webhook")
async def receive_webhook(request: Request):
    try:
        payload = await request.json()
    except Exception:
        return {"ok": False, "error": "invalid json"}

    events = whatsapp.parse_event(payload)
    for event in events:
        data = event["data"]
        customer_id = conversations.get_or_create_customer(data["from"], data.get("name"))
        conv_id = conversations.get_or_create_conversation(customer_id, source="whatsapp")

        ai = detect_intent_and_reply(data["text"], data.get("name"))
        conversations.add_message(conv_id, "in", data["text"], intent=ai["intent"])

        # تمرير للأتمتة
        engine.handle_event(event["trigger"], data)

        # رد تلقائي
        if settings.whatsapp_auto_reply and ai.get("reply"):
            result = whatsapp.send_message(data["from"], ai["reply"])
            if result.get("ok"):
                conversations.add_message(conv_id, "out", ai["reply"], intent="auto_reply")

    return {"ok": True, "events": len(events)}


