"""طبقة Tools/Actions المحددة والآمنة للـ AI Assistant.
الـ AI لا ينفذ كودًا؛ فقط أسماء أدوات مسموحة في قائمة واضحة."""
import logging
from typing import Any, Callable

from app import db
from app.automations.engine import engine
from app.integrations import registry

logger = logging.getLogger("nexa.ai.tools")


def _ok(data: Any = None) -> dict:
    return {"ok": True, "data": data}


def _fail(reason: str) -> dict:
    return {"ok": False, "error": reason}


def get_customer(params: dict) -> dict:
    phone = params.get("phone")
    if not phone:
        return _fail("phone_required")
    rows = db.query(
        "SELECT c.id, c.phone, c.name, COUNT(cv.id) AS conversations "
        "FROM customers c LEFT JOIN conversations cv ON cv.customer_id=c.id "
        "WHERE c.phone=? GROUP BY c.id",
        (phone,),
    )
    return _ok(rows[0] if rows else None)


def save_customer_note(params: dict) -> dict:
    customer_id = params.get("customer_id")
    note = params.get("note")
    if not customer_id or not note:
        return _fail("customer_id_and_note_required")
    db.execute(
        "CREATE TABLE IF NOT EXISTS customer_notes (id INTEGER PRIMARY KEY AUTOINCREMENT, customer_id INTEGER, note TEXT, created_at TEXT)"
    )
    from datetime import datetime, timezone
    db.execute(
        "INSERT INTO customer_notes(customer_id,note,created_at) VALUES(?,?,?)",
        (customer_id, note, datetime.now(timezone.utc).isoformat()),
    )
    return _ok({"saved": True})


def create_automation_event(params: dict) -> dict:
    trigger = params.get("trigger")
    data = params.get("data", {})
    if not trigger:
        return _fail("trigger_required")
    results = engine.handle_event(trigger, data)
    return _ok({"results": results})


def send_whatsapp_message(params: dict) -> dict:
    to, text = params.get("to"), params.get("text")
    if not to or not text:
        return _fail("to_and_text_required")
    wa = registry.get("whatsapp")
    return wa.send_message(to, text)


# --- stubs آمنة: لا تخترع بيانات ---
def search_product(params: dict) -> dict:
    return _fail("product_catalog_not_connected")


def get_product_price(params: dict) -> dict:
    return _fail("product_catalog_not_connected")


def create_order(params: dict) -> dict:
    return _fail("orders_system_not_connected")


def get_order_status(params: dict) -> dict:
    return _fail("orders_system_not_connected")


TOOLS: dict[str, Callable[[dict], dict]] = {
    "get_customer": get_customer,
    "search_product": search_product,
    "get_product_price": get_product_price,
    "create_order": create_order,
    "get_order_status": get_order_status,
    "save_customer_note": save_customer_note,
    "send_whatsapp_message": send_whatsapp_message,
    "create_automation_event": create_automation_event,
}


def execute_tool(name: str, params: dict) -> dict:
    fn = TOOLS.get(name)
    if fn is None:
        logger.warning(f"AI requested unknown tool: {name}")
        return _fail(f"unknown_tool:{name}")
    try:
        return fn(params or {})
    except Exception as e:
        logger.exception(f"tool {name} failed")
        return _fail(str(e))

"""AI Assistant layer: structured response + conversation/customer context + tools."""
import json
import logging
import re
from datetime import datetime, timezone

from app import db
from app.config import settings
from app.services import ai_tools
from app.services.http import post_with_retry

logger = logging.getLogger("nexa.ai")

INTENTS = [
    "greeting", "price_inquiry", "product_inquiry", "order_request",
    "order_status", "complaint", "support", "appointment",
    "information_request", "unknown",
]

SYSTEM_PROMPT = f"""أنت NEXA AI — مساعد أعمال ذكي. حلّل رسالة العميل باستخدام سياق المحادثة وبيانات العميل.
أجب فقط بـ JSON:
{{
  "intent": أحد [{'/'.join(INTENTS)}],
  "confidence": 0..1,
  "reply": "رد قصير مهني بالعربية",
  "entities": {{}},
  "requested_action": {{"tool": "اسم_أداة_من_القائمة أو null", "params": {{}}}} أو null,
  "requires_human": true/false,
  "language": "ar/en/..."
}}
قواعد صارمة:
- لا تخترع أسعارًا أو منتجات أو بيانات عملاء. إن لم تملك المعلومة قل ذلك.
- الأدوات المسموحة فقط: {', '.join(ai_tools.TOOLS.keys())}.
- إذا الطلب حساس أو غير واضح: requires_human=true.
"""


def _customer_context(customer_id: int | None) -> dict:
    if not customer_id:
        return {}
    rows = db.query("SELECT phone, name FROM customers WHERE id=?", (customer_id,))
    return rows[0] if rows else {}


def _conversation_context(conversation_id: int | None, limit: int = 10) -> list[dict]:
    if not conversation_id:
        return []
    rows = db.query(
        "SELECT direction, body, intent FROM messages WHERE conversation_id=? ORDER BY id DESC LIMIT ?",
        (conversation_id, limit),
    )
    return list(reversed(rows))


def _detect_language(text: str) -> str:
    return "ar" if re.search(r"[\u0600-\u06FF]", text) else "en"


def _offline_analyze(text: str) -> dict:
    """محلل محلي حتمي يُستخدم عند غياب AI key — نفس العقد بدون اختراع بيانات."""
    t = text.strip().lower()
    lang = _detect_language(text)

    def has(*words):
        return any(w in t for w in words)

    if has("السلام", "اهلا", "أهلا", "مرحبا", "صباح", "مساء", "hi", "hello"):
        return _resp("greeting", 0.9, "وعليكم السلام! أهلاً بك 🌟 كيف أقدر أساعدك؟", lang)
    if has("بكام", "بكم", "سعر", "الأسعار", "اسعار", "price", "how much"):
        return _resp("price_inquiry", 0.85, "سأتحقق من السعر.", lang, tool="get_product_price")
    if has("منتج", "منتجات", "product", "عندكم"):
        return _resp("product_inquiry", 0.8, "سأبحث عن المنتج.", lang, tool="search_product")
    if has("اطلب", "أطلب", "عايز اطلب", "عايز أطلب", "طلب جديد", "order", "buy", "أشتري"):
        return _resp("order_request", 0.85, "تمام، سأساعدك في الطلب.", lang, tool="create_order")
    if has("فين طلبي", "فين الطلب", "طلبي", "order status", "تتبع", "وصل"):
        return _resp("order_status", 0.85, "سأتحقق من حالة الطلب.", lang, tool="get_order_status")
    if has("مشكلة", "مشكله", "شكوى", "عندي مشكلة", "complaint", "problem"):
        r = _resp("complaint", 0.8, "نعتذر عن المشكلة. سأحوّلك لأحد زملائنا لمساعدتك.", lang)
        r["requires_human"] = True
        return r
    if has("دعم", "support", "مساعدة", "help"):
        return _resp("support", 0.75, "كيف أقدر أساعدك؟ صف المشكلة باختصار.", lang)
    if has("حجز", "موعد", "appointment", "book"):
        return _resp("appointment", 0.8, "سأساعدك في الحجز. ما الموعد المناسب؟", lang)
    if len(t) < 4 or has("؟؟؟؟", "..."):
        r = _resp("unknown", 0.3, "لم أفهم طلبك جيدًا، ممكن توضح أكثر؟", lang)
        r["requires_human"] = True
        return r
    r = _resp("unknown", 0.4, "أحتاج توضيحًا أكثر لفهم طلبك.", lang)
    r["requires_human"] = True
    return r


def _resp(intent, confidence, reply, language, tool=None):
    return {
        "intent": intent,
        "confidence": confidence,
        "reply": reply,
        "entities": {},
        "requested_action": {"tool": tool, "params": {}} if tool else None,
        "requires_human": False,
        "language": language,
    }


def _llm_analyze(text: str, context: list[dict], customer: dict) -> dict | None:
    if not settings.ai_api_key:
        return None
    url = f"{settings.ai_base_url.rstrip('/')}/chat/completions"
    headers = {"Authorization": f"Bearer {settings.ai_api_key}", "Content-Type": "application/json"}
    ctx = "\n".join(f"{'عميل' if m['direction']=='in' else 'نا'}: {m['body']}" for m in context)
    user_msg = f"بيانات العميل: {json.dumps(customer, ensure_ascii=False)}\nسياق المحادثة:\n{ctx}\nالرسالة الحالية: {text}"
    payload = {
        "model": settings.ai_model,
        "messages": [{"role": "system", "content": SYSTEM_PROMPT}, {"role": "user", "content": user_msg}],
        "response_format": {"type": "json_object"},
    }
    try:
        resp = post_with_retry(url, headers=headers, json=payload)
        if resp.status_code >= 400:
            logger.error(f"AI API error {resp.status_code}: {resp.text[:300]}")
            return None
        parsed = json.loads(resp.json()["choices"][0]["message"]["content"])
        if parsed.get("intent") not in INTENTS:
            parsed["intent"] = "unknown"
        for k, d in [("confidence", 0.5), ("reply", ""), ("entities", {}), ("requires_human", False), ("language", _detect_language(text))]:
            parsed.setdefault(k, d)
        action = parsed.get("requested_action")
        if action and action.get("tool") not in ai_tools.TOOLS:
            logger.warning(f"AI requested disallowed tool: {action.get('tool')}")
            parsed["requested_action"] = None
        return parsed
    except Exception as e:
        logger.error(f"AI analyze failed: {e}")
        return None


def handle_message(*, conversation_id: int | None, customer_id: int | None, text: str) -> dict:
    customer = _customer_context(customer_id)
    context = _conversation_context(conversation_id)

    result = _llm_analyze(text, context, customer) or _offline_analyze(text)

    # تنفيذ الأداة المسموحة إن وُجدت
    tool_result = None
    tool_name = None
    if result.get("requested_action") and result["requested_action"].get("tool"):
        tool_name = result["requested_action"]["tool"]
        params = dict(result["requested_action"].get("params") or {})
        if customer.get("phone"):
            params.setdefault("phone", customer["phone"])
        params.setdefault("customer_id", customer_id)
        tool_result = ai_tools.execute_tool(tool_name, params)
        if not tool_result.get("ok") and tool_result.get("error", "").endswith("not_connected"):
            if not result["reply"] or "تحقق" in result["reply"]:
                result["reply"] = "لا أملك هذه المعلومة حاليًا — يلزم ربط النظام الخاص بها. سأحوّل طلبك لفريق الدعم."
                result["requires_human"] = True

    success = tool_result is None or tool_result.get("ok", False)
    result["tool"] = tool_name
    result["tool_result"] = tool_result
    result["success"] = success

    _log_decision(conversation_id, customer_id, result)
    return result


def _log_decision(conversation_id, customer_id, result):
    db.execute(
        "CREATE TABLE IF NOT EXISTS ai_logs (id INTEGER PRIMARY KEY AUTOINCREMENT, conversation_id INTEGER, customer_id INTEGER, intent TEXT, action TEXT, success INTEGER, requires_human INTEGER, created_at TEXT)"
    )
    db.execute(
        "INSERT INTO ai_logs(conversation_id,customer_id,intent,action,success,requires_human,created_at) VALUES(?,?,?,?,?,?,?)",
        (conversation_id, customer_id, result["intent"], result.get("tool"), int(result["success"]), int(result["requires_human"]), datetime.now(timezone.utc).isoformat()),
    )
    logger.info(
        f"AI decision conv={conversation_id} cust={customer_id} intent={result['intent']} action={result.get('tool')} success={result['success']} human={result['requires_human']}"
    )

