import json

from fastapi.testclient import TestClient

from app.main import app

client = TestClient(app)


def wa_payload(text, phone="20111111111", name="Tester"):
    return {"entry": [{"changes": [{"value": {
        "contacts": [{"wa_id": phone, "profile": {"name": name}}],
        "messages": [{"from": phone, "id": "wamid.t", "timestamp": "1", "type": "text", "text": {"body": text}}],
    }}]}]}


def test_webhook_verify_ok():
    r = client.get("/api/whatsapp/webhook", params={"hub.mode": "subscribe", "hub.verify_token": "test_token_123", "hub.challenge": "CH"})
    assert r.status_code == 200 and r.text == "CH"


def test_webhook_verify_forbidden():
    r = client.get("/api/whatsapp/webhook", params={"hub.mode": "subscribe", "hub.verify_token": "wrong", "hub.challenge": "CH"})
    assert r.status_code == 403


def test_webhook_message_flow():
    r = client.post("/api/whatsapp/webhook", json=wa_payload("السلام عليكم"))
    assert r.status_code == 200 and r.json()["events"] == 1
    msgs = client.get("/api/whatsapp/messages").json()
    assert any(m["body"] == "السلام عليكم" and m["intent"] == "greeting" for m in msgs)


def test_automation_still_works():
    client.post("/api/automations/", json={
        "name": "t2", "trigger": "whatsapp.message_received",
        "action": {"type": "log", "params": {"message": "hi"}},
    })
    r = client.post("/api/automations/event", json={"trigger": "whatsapp.message_received", "data": {"from": "+2010"}})
    assert r.json()["results"][0]["ok"] is True

